<script setup>
import {ref,onMounted,computed} from 'vue'
import {request} from './client'
const props=defineProps({member:Object,rooms:Array,sessions:Array})
const tab=ref('Attendance'),room=ref(''),meeting=ref(''),student=ref(''),status=ref('Present'),note=ref(''),rows=ref([]),enrolled=ref([]),tickets=ref([]),selected=ref(null),messages=ref([]),text=ref(''),subject=ref(''),category=ref('Technical'),ticketStatus=ref('Open'),error=ref(''),busy=ref(false),page=ref(0)
const manager=computed(()=>props.member.role!=='Student')
const meetings=computed(()=>props.sessions.filter(s=>s.classroom===room.value))
async function run(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function attendance(){if(!room.value)return;rows.value=await request('operations','attendance',{classroom:room.value,session:meeting.value||null,page:page.value});if(manager.value)enrolled.value=await request('api','enrollments',{classroom:room.value,page:0})}
async function loadTickets(){tickets.value=await request('operations','tickets',{page:page.value})}
async function mark(){await run(async()=>{await request('operations','mark_attendance',{session:meeting.value,student:student.value,status:status.value,note:note.value});await attendance()})}
async function view(t){selected.value=t;ticketStatus.value=t.status;text.value='';await run(async()=>messages.value=await request('operations','thread',{ticket:t.name}))}
async function create(){await run(async()=>{await request('operations','create_ticket',{subject:subject.value,category:category.value,body:text.value});subject.value='';text.value='';await loadTickets()})}
async function reply(){await run(async()=>{await request('operations','reply',{ticket:selected.value.name,body:text.value,status:props.member.role==='Admin'?ticketStatus.value:null});text.value='';messages.value=await request('operations','thread',{ticket:selected.value.name});await loadTickets()})}
function changeTab(t){tab.value=t;page.value=0;run(t==='Support'?loadTickets:attendance)}
onMounted(()=>{room.value=props.rooms[0]?.name||'';run(attendance)})
</script>
<template><section class="operations-space"><div class="page-heading"><div><span class="eyebrow">THE DETAILS THAT KEEP THINGS MOVING</span><h1>Your campus desk.</h1><p>Attendance and support, together in one place.</p></div></div><div class="paper-tabs"><button v-for="t in ['Attendance','Support']" :class="{active:tab===t}" @click="changeTab(t)">{{t}}</button></div><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="tab==='Attendance'"><section class="panel ops-panel"><div class="ops-fields"><label>Classroom<select v-model="room" @change="meeting='';page=0;run(attendance)"><option v-for="r in rooms" :value="r.name">{{r.title}}</option></select></label><label>Session<select v-model="meeting" @change="page=0;run(attendance)"><option value="">All sessions</option><option v-for="s in meetings" :value="s.name">{{s.title}} · {{s.starts_at}}</option></select></label></div><form v-if="manager&&meeting" @submit.prevent="mark"><div class="ops-fields"><label>Enrolled student<select v-model="student" required><option disabled value="">Choose a student</option><option v-for="e in enrolled" :value="e.student">{{e.student}}</option></select></label><label>Status<select v-model="status"><option>Present</option><option>Absent</option><option>Excused</option></select></label><label>Register note<input v-model="note" maxlength="500"></label></div><button class="button primary" :disabled="busy">Save attendance</button><p>Records refer to the selected class session. Repeated online joins do not overwrite a teacher’s register.</p></form><div class="ops-table"><table><thead><tr><th>Student</th><th>Session</th><th>Status</th><th>Channel</th><th>Recorded</th></tr></thead><tbody><tr v-for="a in rows"><td>{{a.student}}</td><td>{{sessions.find(s=>s.name===a.session)?.title||a.session}}</td><td>{{a.status}}</td><td>{{a.channel}}</td><td>{{a.recorded_at}}</td></tr></tbody></table><p v-if="!rows.length">No attendance recorded for this selection.</p></div><div class="inline"><button class="button subtle" :disabled="!page||busy" @click="page--;run(attendance)">Previous</button><button class="button subtle" :disabled="rows.length<100||busy" @click="page++;run(attendance)">Next</button><a v-if="manager&&room" class="text-button" :href="'/api/method/institute_lms.operations.attendance_csv?'+new URLSearchParams({classroom:room,session:meeting,page})">Export this page as CSV</a></div></section></template><template v-else><div class="ops-support"><section class="panel ops-panel"><h2>{{member.role==='Admin'?'Support inbox':'Your support requests'}}</h2><button v-for="t in tickets" class="ops-ticket" @click="view(t)"><strong>{{t.subject}}</strong><small>{{t.category}} · {{t.status}}</small></button><p v-if="!tickets.length">All quiet here. Your support conversations will appear in this space.</p><div class="inline"><button class="button subtle" :disabled="!page||busy" @click="page--;run(loadTickets)">Previous</button><button class="button subtle" :disabled="tickets.length<30||busy" @click="page++;run(loadTickets)">Next</button></div></section><form v-if="!selected" class="panel ops-panel" @submit.prevent="create"><h2>How can we help?</h2><label>Subject<input v-model="subject" required maxlength="120"></label><label>Category<select v-model="category"><option v-for="c in ['Account','Payment','Classroom','Technical','Other']">{{c}}</option></select></label><label>Message<textarea v-model="text" required maxlength="2000"></textarea></label><p>Do not include passwords, verification codes or full payment card details.</p><button class="button primary" :disabled="busy">Create support request</button></form><form v-else class="panel ops-panel" @submit.prevent="reply"><button type="button" class="text-button" @click="selected=null;text=''">New request</button><h2>{{selected.subject}}</h2><article v-for="m in messages" class="ops-message"><small>{{m.author_user}} · {{m.creation}}</small><p>{{m.body}}</p></article><p v-if="messages.length===50">This view shows the first 50 replies. Contact support for older long-thread exports.</p><label>Reply<textarea v-model="text" required maxlength="2000"></textarea></label><label v-if="member.role==='Admin'">Status<select v-model="ticketStatus"><option>Open</option><option>In progress</option><option>Resolved</option></select></label><button class="button primary" :disabled="busy">Send reply</button></form></div></template></section></template>
<style>.ops-panel{padding:28px;margin:20px 0}.ops-fields,.ops-support{display:grid;grid-template-columns:1fr 1fr;gap:22px}.ops-panel label{display:flex;flex-direction:column;gap:10px;font-size:12px;margin:15px 0}.ops-panel :is(input,select,textarea){padding:13px;border:1px solid var(--student-border,#e3d9ed);border-radius:10px;background:var(--student-card,#fff);color:var(--student-ink,#51405b);min-width:0}.ops-panel textarea{min-height:120px}.ops-panel p{font-size:12px;line-height:1.9;margin:18px 0}.ops-table{overflow:auto;margin:20px 0}.ops-table table{width:100%;font-size:12px;border-collapse:collapse}.ops-table :is(th,td){text-align:left;padding:14px;border-bottom:1px solid var(--student-border,#e3d9ed)}.ops-ticket{display:flex;flex-direction:column;gap:10px;padding:20px;width:100%;text-align:left;border:1px solid var(--student-border,#e3d9ed);border-radius:14px;margin:15px 0;background:none;color:inherit;cursor:pointer}.ops-ticket small,.ops-message small{font-size:10px;color:#947eaa}.ops-message{padding:18px 0;border-bottom:1px solid var(--student-border,#e3d9ed)}@media(max-width:650px){.ops-fields,.ops-support{grid-template-columns:1fr}.ops-panel{padding:20px}}</style>
